import { useEffect, useState } from 'react';
import { SlidersHorizontal } from 'lucide-react';
import Alert from '../../../components/ui/Alert.jsx';
import Button from '../../../components/ui/Button.jsx';
import Drawer from '../../../components/ui/Drawer.jsx';
import Input from '../../../components/ui/Input.jsx';
import { createAdjustment } from '../../../services/adjustments.service.js';
import { listDrugs } from '../../../services/drugs.service.js';
import { getDrugInventory } from '../../../services/inventory.service.js';
import { formatDate, formatQuantity } from '../../../utils/format.js';

const adjustmentTypes = [
  { value: 'physical_count', label: 'Physical count correction' },
    { value: 'damage', label: 'Damage' },
      { value: 'loss', label: 'Loss or theft' },
        { value: 'correction', label: 'Data correction' },
          { value: 'expiry_writeoff', label: 'Expiry write-off' },
            { value: 'other', label: 'Other' }
            ];

            const initialForm = {
              drugId: '',
                batchId: '',
                  adjustmentType: 'physical_count',
                    quantity: '',
                      reason: '',
                        reference: ''
                        };

                        export default function AdjustmentFormDrawer({ open, onClose, onSaved }) {
                          const [drugs, setDrugs] = useState([]);
                            const [batches, setBatches] = useState([]);
                              const [form, setForm] = useState(initialForm);
                                const [errors, setErrors] = useState({});
                                  const [error, setError] = useState('');
                                    const [saving, setSaving] = useState(false);
                                      const [loadingBatches, setLoadingBatches] = useState(false);

                                        useEffect(() => {
                                            if (!open) {
                                                  return;
                                                      }
                                                          setForm(initialForm);
                                                              setBatches([]);
                                                                  setErrors({});
                                                                      setError('');
                                                                          listDrugs({ status: 'active', pageSize: 100 })
                                                                                .then((result) => setDrugs(result.items || []))
                                                                                      .catch(() => setDrugs([]));
                                                                                        }, [open]);

                                                                                          const selectDrug = async (event) => {
                                                                                              const drugId = event.target.value;
                                                                                                  setForm((current) => ({ ...current, drugId, batchId: '' }));
                                                                                                      setBatches([]);
                                                                                                          if (!drugId) {
                                                                                                                return;
                                                                                                                    }
                                                                                                                        setLoadingBatches(true);
                                                                                                                            try {
                                                                                                                                  const data = await getDrugInventory(drugId, 90);
                                                                                                                                        setBatches(data.batches || []);
                                                                                                                                            } catch (loadError) {
                                                                                                                                                  setError(loadError.message || 'Batches could not be loaded.');
                                                                                                                                                      } finally {
                                                                                                                                                            setLoadingBatches(false);
                                                                                                                                                                }
                                                                                                                                                                  };

                                                                                                                                                                    const updateField = (field) => (event) => {
                                                                                                                                                                        setForm((current) => ({ ...current, [field]: event.target.value }));
                                                                                                                                                                            setErrors((current) => ({ ...current, [field]: undefined }));
                                                                                                                                                                                if (error) {
                                                                                                                                                                                      setError('');
                                                                                                                                                                                          }
                                                                                                                                                                                            };

                                                                                                                                                                                              const handleSubmit = async (event) => {
                                                                                                                                                                                                  event.preventDefault();

                                                                                                                                                                                                      const nextErrors = {};
                                                                                                                                                                                                          if (!form.drugId) {
                                                                                                                                                                                                                nextErrors.drugId = 'Choose a drug';
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                        if (!form.batchId) {
                                                                                                                                                                                                                              nextErrors.batchId = 'Choose a batch';
                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                      const quantity = Number(form.quantity);
                                                                                                                                                                                                                                          if (!Number.isFinite(quantity) || quantity === 0) {
                                                                                                                                                                                                                                                nextErrors.quantity = 'Enter a positive or negative quantity, not zero';
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                        if (form.reason.trim().length < 3) {
                                                                                                                                                                                                                                                              nextErrors.reason = 'A reason of at least 3 characters is required';
                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                      if (Object.keys(nextErrors).length > 0) {
                                                                                                                                                                                                                                                                            setErrors(nextErrors);
                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                          setSaving(true);
                                                                                                                                                                                                                                                                                              setError('');
                                                                                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                                                                                        const result = await createAdjustment({
                                                                                                                                                                                                                                                                                                                drugId: form.drugId,
                                                                                                                                                                                                                                                                                                                        batchId: form.batchId,
                                                                                                                                                                                                                                                                                                                                adjustmentType: form.adjustmentType,
                                                                                                                                                                                                                                                                                                                                        quantity,
                                                                                                                                                                                                                                                                                                                                                reason: form.reason.trim(),
                                                                                                                                                                                                                                                                                                                                                        reference: form.reference.trim() || null
                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                    onSaved(result);
                                                                                                                                                                                                                                                                                                                                                                        } catch (submitError) {
                                                                                                                                                                                                                                                                                                                                                                              setError(submitError.message || 'The adjustment could not be saved.');
                                                                                                                                                                                                                                                                                                                                                                                  } finally {
                                                                                                                                                                                                                                                                                                                                                                                        setSaving(false);
                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                                                                                                                                                                const selectedBatch = batches.find((batch) => batch.id === form.batchId);

                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                      <Drawer
                                                                                                                                                                                                                                                                                                                                                                                                            open={open}
                                                                                                                                                                                                                                                                                                                                                                                                                  onClose={onClose}
                                                                                                                                                                                                                                                                                                                                                                                                                        title="New stock adjustment"
                                                                                                                                                                                                                                                                                                                                                                                                                              subtitle="Use a negative quantity to reduce stock"
                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                        <form onSubmit={handleSubmit} className="space-y-4" noValidate>
                                                                                                                                                                                                                                                                                                                                                                                                                                                {error ? <Alert tone="error">{error}</Alert> : null}

                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label className="field-label" htmlFor="adjustment-drug">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Drug
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <select id="adjustment-drug" value={form.drugId} onChange={selectDrug} className="field">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <option value="">Select a drug</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {drugs.map((drug) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <option key={drug.id} value={drug.id}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {drug.name} ({drug.code})
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {errors.drugId ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="mt-1.5 text-xs font-medium text-maroon-600">{errors.drugId}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) : null}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label className="field-label" htmlFor="adjustment-batch">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Batch
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  id="adjustment-batch"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              value={form.batchId}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onChange={updateField('batchId')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      className="field"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  disabled={loadingBatches || batches.length === 0}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <option value="">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {loadingBatches ? 'Loading batches…' : 'Select a batch'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {batches.map((batch) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <option key={batch.id} value={batch.id}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {batch.batchNumber} — {formatQuantity(batch.quantity)} on hand, expires{' '}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {formatDate(batch.expiryDate)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {errors.batchId ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="mt-1.5 text-xs font-medium text-maroon-600">{errors.batchId}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) : null}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="grid gap-4 sm:grid-cols-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label className="field-label" htmlFor="adjustment-type">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Adjustment type
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <select
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          id="adjustment-type"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={form.adjustmentType}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={updateField('adjustmentType')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    className="field"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {adjustmentTypes.map((type) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <option key={type.value} value={type.value}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {type.label}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          label="Quantity"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      name="adjustmentQuantity"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  type="number"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              step="any"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={form.quantity}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={updateField('quantity')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  placeholder="-5 or 5"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error={errors.quantity}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          hint={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        selectedBatch
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? `On hand: ${formatQuantity(selectedBatch.quantity)} ${selectedBatch.unitOfMeasure}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : undefined
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        label="Reason"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  name="adjustmentReason"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value={form.reason}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onChange={updateField('reason')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                placeholder="Explain what happened"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          error={errors.reason}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    label="Reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              name="adjustmentReference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        value={form.reference}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onChange={updateField('reference')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder="Optional supporting reference"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex flex-col gap-2 border-t border-sand-200 pt-4 sm:flex-row-reverse">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Button type="submit" loading={saving} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <SlidersHorizontal className="h-4 w-4" aria-hidden="true" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {saving ? 'Saving' : 'Submit adjustment'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Button type="button" variant="outline" onClick={onClose} className="sm:flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Cancel
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </Drawer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }